export const theoryTopics = [
  { title: "Negligence in Road Traffic Accidents", desc: "Elements of duty of care, breach, causation and remoteness in MVA context. The tort of negligence requires proving that the defendant owed a duty of care, breached that duty, and caused foreseeable damage to the plaintiff. The four elements must be pleaded and proved on a balance of probabilities.", category: "Core Principles", statutes: ["Road Transport Act 1987", "Civil Law Act 1956"] },
  { title: "Standard of Care in Driving", desc: "The objective standard of a reasonable, prudent driver applied to road users. Courts assess what a reasonable person in the defendant's position would have done, considering road conditions, visibility, and traffic. Higher standards apply to professional drivers, public service vehicles and commercial transport operators.", category: "Core Principles", statutes: ["Road Transport Act 1987 s.42-45"] },
  { title: "Causation and Remoteness", desc: "The 'but for' test and the Wagon Mound foreseeability rule as applied in Malaysian PI claims. Includes novus actus interveniens, the thin skull rule, multiple causes (material contribution test from Bonnington Castings), and intervening medical negligence.", category: "Core Principles", statutes: ["Civil Law Act 1956"] },
  { title: "Res Ipsa Loquitur", desc: "Application where the accident speaks for itself: the thing causing damage was under the defendant's control, the accident would not ordinarily occur without negligence, and the cause is unknown to the plaintiff. Common in rear-end collisions, single-vehicle accidents on dry roads, and falling objects from vehicles.", category: "Core Principles", statutes: [] },
  { title: "Burden and Standard of Proof", desc: "Plaintiff bears the legal burden of proving negligence on a balance of probabilities (more probable than not). Evidential burden may shift to defendant in res ipsa loquitur cases. Standard is lower than criminal proof beyond reasonable doubt — even where criminal acquittal occurred, civil liability may still attach.", category: "Core Principles", statutes: ["Evidence Act 1950 s.101-104"] },
  { title: "Duty of Care: The Anns/Caparo Test", desc: "Three-stage Caparo test: (1) reasonable foreseeability of harm; (2) sufficient proximity between parties; (3) just, fair and reasonable to impose duty. Applied alongside the neighbour principle from Donoghue v Stevenson. Particularly relevant for novel duty situations and pure economic loss.", category: "Core Principles", statutes: [] },
  { title: "Concurrent Liability in Tort and Contract", desc: "Where parties are also in contractual relationship (e.g. taxi driver/passenger, employer/employee), claims may proceed concurrently in tort and contract. Henderson v Merrett principle adopted in Malaysia. Plaintiff may choose more advantageous limitation period or remedy.", category: "Core Principles", statutes: ["Contracts Act 1950"] },
  { title: "Contributory Negligence", desc: "Apportionment of liability under Civil Law Act 1956, Section 12. Where the plaintiff's own negligence contributed to the injury, damages are reduced by the proportion of fault attributable to the plaintiff. Apportionment based on culpability AND causative potency. Court typically gives precise percentages (10%, 20%, 25%, 30%, etc.).", category: "Defences", statutes: ["Civil Law Act 1956 s.12"] },
  { title: "Volenti Non Fit Injuria", desc: "Defence of voluntary assumption of risk. The defendant must prove the plaintiff had full knowledge of the nature and extent of the risk and freely and voluntarily accepted it. Rarely succeeds in MVA cases — Pitts v Hunt principle that mere knowledge is insufficient. Must show actual consent to bear legal risk.", category: "Defences", statutes: [] },
  { title: "Inevitable Accident", desc: "Defence that the accident was not caused by want of reasonable care but by circumstances beyond the defendant's control. Requires proof that the event was physically unavoidable despite reasonable care — sudden mechanical failure not previously detectable, sudden medical emergency (heart attack while driving), or unforeseen road obstacle.", category: "Defences", statutes: [] },
  { title: "Act of God (Vis Major)", desc: "Defence available where damage is caused by extraordinary natural forces that could not have been foreseen or guarded against. Extremely narrow application in MVA claims — flash floods, landslides may qualify only if truly extraordinary. Rylands v Fletcher principle considered.", category: "Defences", statutes: [] },
  { title: "Ex Turpi Causa (Illegality)", desc: "Defence that the plaintiff's claim arises from their own illegal conduct. Limited application — even drunk drivers and illegal racers may recover, subject to substantial contributory negligence reduction. Public policy considerations weighed against claimant's right to compensation.", category: "Defences", statutes: [] },
  { title: "Necessity and Self-Defence", desc: "Defences where action taken to prevent greater harm or in self-protection. Limited application in MVA — driver swerving to avoid child may be excused for damaging parked vehicle. Must show actions were proportionate and reasonable in the emergency.", category: "Defences", statutes: [] },
  { title: "Vicarious Liability", desc: "Employer-employee relationship and owner-driver liability. An employer is liable for torts committed by employees acting in the course of employment. Key issue: was the employee on a frolic of his own? Mohamud v Morrison test of 'sufficient connection' between wrongful act and employment.", category: "Liability", statutes: ["Road Transport Act 1987 s.96"] },
  { title: "Owner's Liability for Vehicle", desc: "Registered owner of motor vehicle presumed liable for negligent driving by anyone using the vehicle with consent. Statutory presumption under RTA. Owner may rebut by proving vehicle was being used without consent or by an unauthorized person.", category: "Liability", statutes: ["Road Transport Act 1987"] },
  { title: "Occupier's Liability", desc: "Duty owed to lawful visitors, licensees, trespassers and categories of entrants. Includes duty to maintain premises in reasonably safe condition and to warn of hidden dangers. Special duty to children under doctrine of allurement (attractive nuisance).", category: "Liability", statutes: ["Occupiers' Liability Act (UK applied)"] },
  { title: "Employer's Liability", desc: "Common law duty to provide competent fellow workers, proper plant and equipment, a safe system of work, and adequate supervision. Overlaps with OSHA 1994 statutory duties. Non-delegable duty — cannot escape by hiring independent contractor.", category: "Liability", statutes: ["OSHA 1994", "FMA 1967"] },
  { title: "Product Liability", desc: "Manufacturer's duty of care under Donoghue v Stevenson principles and statutory liability under Consumer Protection Act 1999. Includes defective vehicles, auto parts, helmets, child seats. Strict liability under Part X CPA — no need to prove negligence for consumer products.", category: "Liability", statutes: ["Consumer Protection Act 1999 Part X"] },
  { title: "Government & Statutory Body Liability", desc: "Liability of government bodies for negligent road maintenance, design defects, and failure to provide adequate signage. Application of Government Proceedings Act 1956. Section 5 Notice required for actions against government within 36 months of accrual.", category: "Liability", statutes: ["Government Proceedings Act 1956", "Federal Roads Act 1959"] },
  { title: "Joint and Several Liability", desc: "Where multiple tortfeasors cause indivisible harm, each is liable for full damages (joint and several). Plaintiff may sue any one or all. Defendant may seek contribution from co-tortfeasors under Civil Law Act 1956 s.10. Common in multi-vehicle pile-ups.", category: "Liability", statutes: ["Civil Law Act 1956 s.10, s.11"] },
  { title: "Concurrent Liability (Multiple Defendants)", desc: "Multi-vehicle accidents and contribution between defendants. Apportionment of fault between joint tortfeasors. Strategic considerations for joining all potential defendants vs single deep-pocket defendant. Third party proceedings under O.16 ROC.", category: "Liability", statutes: ["Civil Law Act 1956 s.10", "Rules of Court 2012 O.16"] },
  { title: "Liability of Pillion Riders & Passengers", desc: "Passengers generally cannot be contributorily negligent unless they accept ride from obviously drunk driver, fail to wear seatbelt/helmet, distract driver, or interfere with controls. Passenger may sue both drivers in collision.", category: "Liability", statutes: [] },
  { title: "Assessment of General Damages", desc: "Principles governing non-pecuniary loss: pain and suffering, loss of amenities of life. Courts refer to comparable awards, Practitioner's Library tables, and the nature/severity of injuries. Court of Appeal Quantum Tables provide standardized starting figures.", category: "Damages", statutes: ["Civil Law Act 1956 s.28A"] },
  { title: "Assessment of Special Damages", desc: "Pecuniary losses that must be specifically pleaded and strictly proved: medical expenses, transport costs, repair costs, loss of earnings (pre-trial), cost of nursing care, aids and appliances. Each item requires documentary proof — receipts, invoices, statements.", category: "Damages", statutes: [] },
  { title: "Future Loss of Earnings", desc: "The multiplier-multiplicand method: annual loss (multiplicand) multiplied by a figure reflecting years of future loss (multiplier), discounted for contingencies and accelerated receipt. Multiplier capped at retirement age (60). Deduction of EPF contributions but not income tax.", category: "Damages", statutes: ["Civil Law Act 1956 s.28A(2)(c)"] },
  { title: "Loss of Earning Capacity", desc: "Awarded when the plaintiff is at a disadvantage in the labour market but has not suffered actual loss of earnings. Distinguished from future loss of earnings. Applies to self-employed, young claimants, and those with disability affecting future job prospects.", category: "Damages", statutes: [] },
  { title: "Bereavement Damages", desc: "Fixed statutory award under Section 7(3A) of the Civil Law Act 1956. Currently RM30,000 (as amended). Awarded only to spouse or to parents of unmarried minor. Does NOT include children of deceased adult.", category: "Damages", statutes: ["Civil Law Act 1956 s.7(3A)"] },
  { title: "Future Medical & Care Expenses", desc: "Cost of future surgery, medication, physiotherapy, nursing care, rehabilitation. Must be supported by specialist quotation or expert evidence. May be awarded as lump sum or, in catastrophic cases, considered for periodical payments. Includes home modifications and transport adaptations.", category: "Damages", statutes: ["Civil Law Act 1956 s.28A"] },
  { title: "Cost of Aids and Appliances", desc: "Wheelchairs, crutches, prosthetics, orthotics, special beds, hoists, communication devices. Includes replacement costs over plaintiff's lifetime. Must consider obsolescence, wear-and-tear and maintenance. Specialist evidence required for complex equipment.", category: "Damages", statutes: [] },
  { title: "Provisional Damages", desc: "Court may award provisional damages where there is a chance of significant deterioration of plaintiff's condition. Plaintiff may return for further damages if deterioration occurs. Mohamed Raihan v Kerajaan Malaysia recognized provisional damages in Malaysia.", category: "Damages", statutes: [] },
  { title: "Aggravated and Exemplary Damages", desc: "Aggravated damages compensate for additional injury to dignity and feelings caused by defendant's conduct. Exemplary (punitive) damages punish reprehensible conduct. Rookes v Barnard categories applied — limited to specific situations in Malaysia.", category: "Damages", statutes: [] },
  { title: "Interest on Damages", desc: "General damages: 5% p.a. from date of service of writ to date of judgment. Special damages: 5% p.a. from date of accident to date of judgment (some cases say 2.5% as average). Post-judgment interest at 5% p.a. or as ordered. Court has discretion under Civil Law Act s.11.", category: "Damages", statutes: ["Civil Law Act 1956 s.11"] },
  { title: "Fatal Accident Claims (Dependency)", desc: "Dependency claims under Sections 7 & 8 of the Civil Law Act 1956. The estate and dependants' claims, apportioning the deceased's income, deducting personal living expenses, selecting the multiplier. Loss of services (housekeeping, childcare) also claimable.", category: "Claims", statutes: ["Civil Law Act 1956 s.7, s.8"] },
  { title: "Estate Claims", desc: "Claims by the estate of a deceased person for losses between the date of injury and death. Includes pain and suffering (if conscious), loss of earnings, and medical expenses before death. Must be brought by personal representatives — letter of administration or probate required.", category: "Claims", statutes: ["Civil Law Act 1956 s.8", "Probate and Administration Act 1959"] },
  { title: "Minor's Claims & Litigation Friend", desc: "Procedural requirements for bringing claims on behalf of minors. Appointment of next friend/litigation friend, approval of settlements by court (O.76 r.10), payment into court for investment. Settlement without sanction is voidable at minor's option.", category: "Claims", statutes: ["Rules of Court 2012 O.76"] },
  { title: "Mental Patients & Disabled Persons", desc: "Claims by persons of unsound mind require committee or guardian. Mental Health Act 2001 provisions. Court approval required for compromise. Considerations of capacity to instruct solicitors and give evidence.", category: "Claims", statutes: ["Mental Health Act 2001", "Rules of Court 2012 O.76"] },
  { title: "Limitation Period", desc: "6-year limitation under Limitation Act 1953 s.6(1)(a) for personal injury. Special rules: time does not run against minors (s.24), persons of unsound mind, or where fraud/concealment applies. Limitation MUST be pleaded as a defence — court will not raise it sua sponte.", category: "Procedure", statutes: ["Limitation Act 1953 s.6, s.24"] },
  { title: "Running Down Cases Procedure", desc: "Special procedural rules under Order 22A of the Rules of Court. Motor accident cases procedure, mandatory mediation, joint trial of liability and quantum, and pre-trial case management. RD Form mandatory for all motor accident claims.", category: "Procedure", statutes: ["Rules of Court 2012 O.22A"] },
  { title: "Notice of Demand (Section 96 RTA)", desc: "Mandatory pre-action notice to the insurer under Section 96 of the Road Transport Act 1987. Must be served before commencing proceedings. Must specify particulars of claim, date of accident, vehicle details. Non-compliance bars direct enforcement against insurer.", category: "Procedure", statutes: ["Road Transport Act 1987 s.96"] },
  { title: "Section 5 Notice (Government Proceedings)", desc: "Mandatory notice under Public Authorities Protection Act / GP Act before suing government. 36 months limitation from accrual of cause of action. Notice must specify particulars of claim. Strict compliance required — non-compliance fatal to claim.", category: "Procedure", statutes: ["Government Proceedings Act 1956", "Public Authorities Protection Act 1948"] },
  { title: "Interim Payments", desc: "Application for interim payment of damages under Order 29 Rules of Court. Requirements: admission of liability or judgment on liability obtained. Court's discretion in quantum — typically conservative percentage of likely award. Payment is reckonable against final damages.", category: "Procedure", statutes: ["Rules of Court 2012 O.29"] },
  { title: "Mediation in PI Cases", desc: "Court-annexed mediation for running down cases. Practice Direction on mediation, judge-led mediation process, duties of parties, and consequences of unreasonable refusal to mediate. Calderbank offers and without prejudice negotiations.", category: "Procedure", statutes: ["Mediation Act 2012", "Practice Direction 4/2016"] },
  { title: "Summary Judgment (O.14)", desc: "Application for judgment without trial where defendant has no real prospect of successfully defending the claim. Common in clear-liability cases (rear-end collisions, admitted fault). Defendant must show triable issue or some other reason for trial. Conditional leave to defend possible.", category: "Procedure", statutes: ["Rules of Court 2012 O.14"] },
  { title: "Striking Out (O.18 r.19)", desc: "Application to strike out pleadings or claim that disclose no reasonable cause of action, are scandalous/frivolous/vexatious, or abuse of process. Also under inherent jurisdiction. High threshold — claim must be obviously unsustainable.", category: "Procedure", statutes: ["Rules of Court 2012 O.18 r.19"] },
  { title: "Discovery and Inspection (O.24)", desc: "Mutual exchange of relevant documents. List of Documents (Form 37) followed by inspection. Specific discovery for particular documents. Privilege claims (legal advice, litigation, without prejudice). Sanctions for non-compliance include unless orders and striking out.", category: "Procedure", statutes: ["Rules of Court 2012 O.24"] },
  { title: "Interrogatories (O.26)", desc: "Written questions served on opposing party requiring sworn answers. Must be relevant to issues in dispute. Cannot be used as fishing expedition. Useful for pinning down opponent's case on liability and damages.", category: "Procedure", statutes: ["Rules of Court 2012 O.26"] },
  { title: "Third Party Proceedings (O.16)", desc: "Defendant may bring in third party for contribution, indemnity, or relief. Third party notice issued with leave (or as of right in some cases). Common in multi-vehicle accidents to bring in another driver or vehicle owner.", category: "Procedure", statutes: ["Rules of Court 2012 O.16", "Civil Law Act 1956 s.10"] },
  { title: "Setting Aside Default Judgment", desc: "Application under O.13 r.8 or O.42 r.13 to set aside judgment in default. Must show: meritorious defence, reason for delay, and that it would be just to set aside. Conditional setting aside (e.g. payment into court) common.", category: "Procedure", statutes: ["Rules of Court 2012 O.13, O.42"] },
  { title: "Amendment of Pleadings (O.20)", desc: "Application to amend SOC or defence. Liberal approach — amendments allowed unless prejudice to other party that cannot be compensated by costs. Limitation issues critical — new cause of action after limitation generally not allowed.", category: "Procedure", statutes: ["Rules of Court 2012 O.20"] },
  { title: "Security for Costs (O.23)", desc: "Application to require plaintiff to provide security for defendant's costs. Available against foreign plaintiffs, plaintiffs with no fixed address, or where plaintiff is impecunious company. Court balances access to justice against legitimate protection of defendant.", category: "Procedure", statutes: ["Rules of Court 2012 O.23"] },
  { title: "Stay of Proceedings", desc: "Application to stay proceedings pending: (a) settlement negotiations; (b) related criminal proceedings; (c) parallel arbitration; (d) appeal. Court has inherent jurisdiction. Considerations include prejudice, public interest, overlapping issues.", category: "Procedure", statutes: ["Courts of Judicature Act 1964", "Rules of Court 2012"] },
  { title: "Injunctions in PI Cases", desc: "Mareva (freezing) injunctions to prevent dissipation of assets pending judgment. Anton Piller orders for preservation of evidence. Required: good arguable case, real risk of dissipation/destruction, balance of convenience.", category: "Procedure", statutes: ["Specific Relief Act 1950", "Rules of Court 2012 O.29"] },
  { title: "Costs (O.59)", desc: "Costs follow the event — successful party generally entitled to costs. Standard basis (party-and-party) vs indemnity basis. Calderbank offers and Part 36-equivalent offers affect costs orders. Allocatur for assessment of costs.", category: "Procedure", statutes: ["Rules of Court 2012 O.59"] },
  { title: "Third Party Motor Insurance", desc: "Compulsory third-party insurance under the Road Transport Act 1987. Scope of coverage, rights of third parties against insurers, duty to satisfy judgments, and exceptions to coverage. Insurer's right to defend in name of insured.", category: "Insurance", statutes: ["Road Transport Act 1987 Part IV"] },
  { title: "Motor Insurers' Bureau (MIB)", desc: "Coverage for victims of uninsured and untraced drivers. The MIB agreement, conditions for claiming, exclusions (e.g. terrorism, no police report within 14 days for hit-and-run), and the compensation scheme for hit-and-run accidents.", category: "Insurance", statutes: ["Motor Insurers Bureau Agreement"] },
  { title: "SOCSO / PERKESO Claims", desc: "Social Security Organization benefits for employment injuries. Interaction between SOCSO benefits and civil claims, deduction rules (50% of received benefits typically deducted from special damages), and concurrent entitlements. SOCSO has subrogation rights.", category: "Insurance", statutes: ["Employees' Social Security Act 1969"] },
  { title: "Subrogation Rights of Insurers", desc: "Insurer's right of subrogation after payment. How insurers recover from third parties, interaction with the insured's claim, and the rule against double recovery. Insured may not compromise rights against tortfeasor without insurer's consent.", category: "Insurance", statutes: ["Road Transport Act 1987 s.96"] },
  { title: "Insurance Repudiation Defences", desc: "Grounds insurer may repudiate liability: breach of policy conditions, non-disclosure of material facts, fraud, driving without licence, driving under influence. Section 96 RTA limits defences against third parties — Wong Yuen Hock v Syarikat Hong Leong Assurance principles.", category: "Insurance", statutes: ["Road Transport Act 1987 s.96", "Insurance Act 1996"] },
  { title: "Knock-for-Knock Agreements", desc: "Industry agreements between insurers where each pays own insured's losses without pursuing recovery. Does not affect injured third parties' rights. Important when assessing tactical considerations and likely insurer behaviour.", category: "Insurance", statutes: [] },
  { title: "Medical Evidence in PI Cases", desc: "Role of medical reports, expert witnesses, and specialist evidence. Requirements for medical reports, challenging medical evidence, and the court's approach to conflicting medical opinions. Section 45 Evidence Act on expert opinion.", category: "Evidence", statutes: ["Evidence Act 1950 s.45"] },
  { title: "Police Reports and Sketch Plans", desc: "Admissibility and weight of police investigation papers, sketch plans, and accident reconstruction evidence. IO's testimony and the investigative process. Rough vs key sketch plans — admissibility issues. Public document under Evidence Act.", category: "Evidence", statutes: ["Evidence Act 1950", "Criminal Procedure Code"] },
  { title: "Accident Reconstruction Evidence", desc: "Expert evidence on speed calculations from skid marks, point of impact, vehicle damage analysis. Forensic engineers, traffic accident reconstruction specialists. Increasingly important in disputed liability cases.", category: "Evidence", statutes: ["Evidence Act 1950 s.45"] },
  { title: "CCTV and Dashcam Evidence", desc: "Increasingly common — admissibility under Evidence Act s.90A (computer-generated evidence). Chain of custody must be established. Authentication by witness who downloaded/preserved the recording. Continuity of evidence essential.", category: "Evidence", statutes: ["Evidence Act 1950 s.90A, s.73A"] },
  { title: "Proof of Loss & Documentary Evidence", desc: "Proving special damages through receipts, invoices, wage slips, EPF statements, and tax returns. The burden of proof and the standard required for different heads of damage. Original documents required unless secondary evidence admissible.", category: "Evidence", statutes: ["Evidence Act 1950"] },
  { title: "Witness Statements & Testimony", desc: "Affidavits of evidence-in-chief (AEIC) under O.38 r.2A. Witness statement procedure, rules on inadmissible evidence (hearsay, opinion of lay witness), and cross-examination strategy. Hostile witness procedure under Evidence Act s.154.", category: "Evidence", statutes: ["Evidence Act 1950", "Rules of Court 2012 O.38"] },
  { title: "Standard of Care — Children & Learner Drivers", desc: "Children below 7 generally cannot be contributorily negligent (Mullin v Richards). Learner drivers held to standard of competent driver — Nettleship v Weston principle adopted in Malaysia.", category: "Core Principles", statutes: [] },
  { title: "Drunk Driver & Intoxication", desc: "Driving under influence creates near-conclusive presumption of negligence. Voluntary acceptance of lift from drunk driver may amount to volenti or contributory negligence (typically 20-30%) under Owen v Brimmell. Insurer entitled to recover from insured under policy exclusions.", category: "Liability", statutes: ["Road Transport Act 1987 s.45"] },
  { title: "Sudden Medical Emergency Defence", desc: "Driver suddenly incapacitated by unforeseen medical event (heart attack, seizure) may be excused if (1) genuinely sudden, (2) no prior warning, (3) reasonable steps to manage condition. Mansfield v Weetabix.", category: "Defences", statutes: [] },
  { title: "Inevitable Accident & Emergency Doctrine", desc: "Inevitable accident is complete defence — narrowly construed. Emergency doctrine (agony of the moment): driver not negligent for choosing wrong course in sudden emergency not caused by their own fault.", category: "Defences", statutes: [] },
  { title: "Pure Economic Loss Rule", desc: "Generally not recoverable in tort except where Hedley Byrne special relationship exists. Affects vehicle write-off losses, lost business opportunities, secondary economic consequences of accident.", category: "Core Principles", statutes: [] },
  { title: "Psychiatric Injury (Nervous Shock)", desc: "Recoverable only if recognised psychiatric illness. Primary victims (zone of danger) — full recovery. Secondary victims must satisfy Alcock control mechanisms: close ties of love and affection, proximity in time/space, perception by own senses, sudden shock.", category: "Damages", statutes: [] },
  { title: "Nervous Shock — Bystanders & Rescuers", desc: "Bystanders rarely recover unless extraordinary horror. Rescuers may be primary victims (Chadwick v BR) if reasonably foreseeable rescuer would attend and risk physical/psychiatric harm.", category: "Damages", statutes: [] },
  { title: "Bolam-Bolitho Test (Medical Negligence)", desc: "Bolam — practice accepted as proper by responsible body of medical opinion not negligent. Bolitho refinement — court can reject medical opinion if not logically defensible. Foo Fio Na adopted Rogers v Whitaker for informed consent.", category: "Medical Standards", statutes: [] },
  { title: "Doctrine of Informed Consent", desc: "Doctor's duty to disclose material risks to enable patient to make informed decision. Foo Fio Na adopted Rogers v Whitaker — material if reasonable patient would attach significance OR doctor knows particular patient would. Departure from paternalistic Bolam.", category: "Medical Standards", statutes: [] },
  { title: "Loss of Chance in Medical Negligence", desc: "Gregg v Scott — claimant cannot recover for loss of less than 50% chance of better outcome. Causation requires balance of probabilities the negligence caused or materially contributed to harm.", category: "Medical Standards", statutes: [] },
  { title: "Vehicle Owner's Liability", desc: "Owner liable as principal where driver acting as agent. Morgans v Launchbury — purpose of journey must be in furtherance of owner's interest. Important where driver impecunious — owner often co-defendant for asset reach.", category: "Vicarious Liability", statutes: [] },
  { title: "Course of Employment", desc: "Employer vicariously liable only for torts in course of employment. Frolic of one's own breaks the chain. Lister v Hesley Hall — close connection test for intentional torts. Mohamud v Morrisons broadens application.", category: "Vicarious Liability", statutes: [] },
  { title: "Independent Contractor Distinction", desc: "Generally no vicarious liability for independent contractor's torts. Exceptions: non-delegable duties (employer's primary duty), inherently dangerous activities, statutory duties, work performed under direct supervision.", category: "Vicarious Liability", statutes: [] },
  { title: "Gratuitous Care & Hunt v Severs", desc: "Cost of care provided gratuitously by family member recoverable as damages held on trust for the carer. Cannot recover where carer is the tortfeasor. Commercial rate adjusted for family discount typically applied.", category: "Damages", statutes: [] },
  { title: "Loss of Marriage Prospects", desc: "Recoverable head of damage where injury causes physical disfigurement or psychiatric impact reducing marriage prospects. Modest awards. Hicks v Chief Constable — relevance for fatal claims involving young unmarried plaintiffs.", category: "Damages", statutes: [] },
  { title: "Future Care Costs Methodology", desc: "Calculated using multiplier-multiplicand. Annual cost based on Life Care Plan. Multiplier reflects life expectancy. Discount for early receipt typically not applied in Malaysia.", category: "Damages", statutes: [] },
  { title: "Cost of Future Surgery & Treatment", desc: "Recoverable on producing specialist quotation and evidence of necessity. Court considers probability of treatment being undertaken, comparable costs in private vs public sector, life expectancy.", category: "Damages", statutes: [] },
  { title: "Special Accommodation & Equipment", desc: "Recoverable where injury requires modified housing or specialised equipment. Roberts v Johnstone — additional capital cost calculated as notional rental. Wheelchair, hoists, modified vehicle, ramps.", category: "Damages", statutes: [] },
  { title: "Interest on Damages — Detailed Rules", desc: "General damages: 5% from service of writ to judgment. Special damages: 5% (some say 2.5%) from accident to judgment. Future losses: no interest. Post-judgment: 5% until satisfaction. Court has discretion under s.11 Civil Law Act.", category: "Damages", statutes: ["Civil Law Act 1956 s.11"] },
  { title: "Court-Annexed Mediation", desc: "Practice Direction 4/2016 — court may direct mediation. Confidential, without prejudice. Mediator from court panel. Parties must attend with authority to settle. Settlement recorded as consent judgment or Tomlin Order.", category: "Procedure", statutes: ["Practice Direction 4/2016"] },
  { title: "Pre-Trial Case Management (PTCM)", desc: "Mandatory under O.34. Judge actively manages case — directions for pleadings, discovery, interrogatories, bundles, expert evidence. Failure to comply may result in unless orders or striking out.", category: "Procedure", statutes: ["Rules of Court 2012 O.34"] },
  { title: "Calderbank & Without Prejudice Offers", desc: "Calderbank offer — without prejudice save as to costs. If beneficiary fails to beat the offer at trial, costs may be ordered against them from date of offer. Powerful tool for defendants to manage costs exposure.", category: "Procedure", statutes: [] },
  { title: "Wasted Costs Orders", desc: "Court may order legal representative personally liable for costs wasted by improper, unreasonable or negligent conduct. Three-stage test from Ridehalgh v Horsefield. Limited application but powerful sanction.", category: "Procedure", statutes: [] },
  { title: "Indemnity vs Standard Costs", desc: "Standard basis (party-party): proportionate, doubts resolved in favour of paying party. Indemnity basis: doubts in favour of receiving party — reflects court disapproval of conduct. Reserved for unreasonable conduct.", category: "Costs", statutes: ["Rules of Court 2012 O.59"] },
  { title: "Anti-Suit Injunctions", desc: "Court may restrain party from pursuing parallel proceedings in foreign court. Used in cross-border MVA where forum shopping risk. Requires sufficient connection to Malaysia and vexatious foreign proceedings.", category: "Procedure", statutes: [] },
  { title: "Foreign Judgments & Reciprocal Enforcement", desc: "Reciprocal Enforcement of Judgments Act 1958 — registration of foreign judgments from listed Commonwealth countries. Common law enforcement otherwise. Important for cross-border insurer disputes.", category: "Enforcement", statutes: ["Reciprocal Enforcement of Judgments Act 1958"] },
  { title: "Personal Data Protection (Amendment) Act 2024 — Impact on PI Practice", desc: "Act A1727 introduces mandatory data breach notification to PDP Commissioner and affected data subjects, requires appointment of a Data Protection Officer, and increases penalties. Directly affects law firms, insurers and hospitals handling claimant medical records, statements and settlement data. Practitioners should review intake, file storage and retention practices.", category: "Procedure", statutes: ["PDPA 2010 (Act 709)", "PDPA (Amendment) Act 2024 (Act A1727)"] },
  { title: "Solicitors' Remuneration Order 2023 (SRO 2023)", desc: "SRO 2023 governs non-contentious work remuneration. Contentious PI work is generally outside SRO, but solicitors must still observe the Legal Profession Act 1976 and Bar Council Rulings on costs disclosure, taxation and client account. Always document the basis of charge in the retainer letter.", category: "Procedure", statutes: ["Legal Profession Act 1976", "Solicitors' Remuneration Order 2023"] },
  { title: "Conditional Fee Arrangements (PI) — Bar Council Rules", desc: "The Legal Profession (Practice and Etiquette) Rules and Bar Council rulings permit conditional fee arrangements in personal injury matters subject to strict conditions: written agreement, fair percentage of recovery, no champertous element, and client must receive independent advice. Always reduce arrangement to a clear retainer.", category: "Procedure", statutes: ["Legal Profession Act 1976", "Bar Council Rulings"] },
  { title: "Rules of Court 2012 — Consolidated 1 January 2025", desc: "ROC 2012 was consolidated via P.U.(A) 229/2023 and took consolidated effect on 1 January 2025. Cite the consolidated version in post-2025 pleadings and ensure precedents reference the correct rule numbering.", category: "Procedure", statutes: ["Rules of Court 2012", "P.U.(A) 229/2023"] },
  { title: "Insurer's Post-Sa'Amran Liability Under s.96 RTA 1987", desc: "Following AmGeneral v Sa'Amran [2022] 8 CLJ 175, the insurer's statutory duty to satisfy a third-party judgment under s.96 RTA 1987 is strict, subject only to grounds preserved by the policy and the Act. Practitioners should ensure s.96 notice is served promptly and pleaded clearly.", category: "Insurance", statutes: ["Road Transport Act 1987 s.96"] },
  { title: "Multiplier–Multiplicand Method for Future Loss", desc: "The standard method for assessing future loss of earnings and dependency. The multiplicand is the annual net loss; the multiplier is the number of years' purchase, discounted for accelerated receipt and contingencies (the 'vicissitudes of life'). Malaysian courts apply conventional multipliers capped by retirement age and s.28A Civil Law Act 1956 for living plaintiffs. Always show the arithmetic in submissions and plead the components.", category: "Damages", statutes: ["Civil Law Act 1956 s.28A"] },
  { title: "Loss of Earning Capacity (Smith v Manchester Award)", desc: "Where a plaintiff has returned to work but is disadvantaged on the open labour market should they lose the present job, a lump-sum Smith v Manchester award compensates the weakened competitive position. Distinct from loss of future earnings (an actual continuing loss). Quantum is impressionistic — typically a number of months' salary — and must be specifically claimed and supported by medical evidence of residual disability.", category: "Damages", statutes: ["Civil Law Act 1956"] },
  { title: "Dependency Claims under s.7 Civil Law Act 1956", desc: "On a wrongful death, dependants may claim loss of support. The dependency is calculated by the multiplier–multiplicand method on the deceased's net income less personal/living expenses (the conventional deduction is one-third for a married deceased). Section 7(3)(iv) excludes certain benefits from deduction. Bereavement of RM30,000 under s.7(3A) and reasonable funeral expenses are recoverable. Dependants must be pleaded with their relationship and degree of dependency.", category: "Claims", statutes: ["Civil Law Act 1956 s.7", "Civil Law Act 1956 s.7(3A)"] },
  { title: "Estate Claims under s.8 Civil Law Act 1956", desc: "The estate of a deceased may claim losses suffered between injury and death — pre-death pain and suffering (if the deceased was conscious), pre-death medical expenses, and funeral expenses. Damages for loss of expectation of life and lost-years earnings are restricted by statute. Estate claims (s.8) and dependency claims (s.7) may run together but double recovery is not permitted — credit must be given.", category: "Claims", statutes: ["Civil Law Act 1956 s.8"] },
  { title: "Cost of Special Accommodation (Roberts v Johnstone)", desc: "Catastrophically injured plaintiffs may need specially adapted housing. The capital cost of buying suitable accommodation is not recoverable in full (it remains an asset), so courts award the annual cost of the additional capital tied up, using the Roberts v Johnstone approach, plus the cost of adaptations. Requires accommodation and occupational therapy expert evidence.", category: "Damages", statutes: ["Civil Law Act 1956"] },
  { title: "Future Cost of Care & Life Care Plans", desc: "For serious injuries, future care is often the largest head of loss. A Life Care Plan, prepared by a care expert with input from treating clinicians, itemises lifetime needs — nursing/attendant care, equipment, therapy, transport, case management and accommodation. Each item is costed and projected using an appropriate multiplier. Gratuitous care by family is recoverable (commercial rate, discounted).", category: "Damages", statutes: ["Civil Law Act 1956"] },
  { title: "Seat Belt and Crash Helmet Reductions", desc: "Failure to wear a seat belt or a properly fastened crash helmet is contributory negligence reducing damages, even though it does not cause the accident. Malaysian courts adopt graduated reductions broadly following Froom v Butcher: typically up to 25% where the protection would have prevented the injury entirely, around 15% where it would have reduced the injury, and nil where it would have made no difference. The defendant bears the evidential burden.", category: "Defences", statutes: ["Civil Law Act 1956 s.12"] },
  { title: "Vicarious Liability of Employers and Vehicle Owners", desc: "An employer is vicariously liable for torts committed by an employee in the course of employment, including negligent driving by drivers, despatch riders and PSV operators. A registered vehicle owner who permits another to drive may be liable. The 'frolic of his own' principle limits liability where the employee acts outside the scope of employment. Plead the employment relationship and course of employment expressly.", category: "Liability", statutes: ["Civil Law Act 1956"] },
  { title: "Intervening Medical Negligence (Bolam–Bolitho)", desc: "Where negligent medical treatment after the accident worsens the injury, the original tortfeasor remains liable unless the treatment was so grossly negligent as to break the chain of causation (novus actus). The standard of medical care is assessed by the Bolam test as refined by Bolitho (the practice must withstand logical scrutiny); for advice/disclosure, Malaysia applies the Rogers v Whitaker / Foo Fio Na patient-centred standard.", category: "Core Principles", statutes: ["Civil Law Act 1956"] },
  { title: "Interest on Damages (s.11 Civil Law Act 1956)", desc: "The court has discretion to award interest on damages. Conventional practice: special damages carry interest at half the judgment rate from date of accident to judgment; general damages for pain and suffering carry interest from date of service of writ to judgment; future losses carry no interest. Post-judgment interest runs at the prescribed rate until satisfaction. Always claim interest expressly in the prayer.", category: "Damages", statutes: ["Civil Law Act 1956 s.11", "Rules of Court 2012 O.42 r.12"] },
  { title: "Mitigation of Loss in Personal Injury Claims", desc: "A plaintiff must take reasonable steps to mitigate loss — undergoing reasonable medical treatment, attempting suitable alternative employment, and not unreasonably refusing recommended surgery. The burden of proving failure to mitigate rests on the defendant. Unreasonable refusal of treatment that would have reduced the loss may reduce recoverable damages.", category: "Damages", statutes: ["Civil Law Act 1956"] },
  { title: "Court Hierarchy and Monetary Jurisdiction (PI Claims)", desc: "Forum depends on the amount claimed: Magistrates' Court up to RM100,000; Sessions Court up to RM1,000,000 (unlimited for MVA personal injury and fatal accident claims under the Subordinate Courts Act); High Court above RM1,000,000 and for unlimited claims. Appeals lie from Magistrates/Sessions to the High Court, then to the Court of Appeal, and on leave to the Federal Court on questions of public importance.", category: "Procedure", statutes: ["Subordinate Courts Act 1948", "Courts of Judicature Act 1964"] },
];

